R(6387863,"سیب، کرین بیری اور کیلیفورنیا کھجور کا اوٹ میل بیک","یہ سیب، کرین بیری اور کھجور کا اوٹ بیک ایک بھرپور ترکیب ہے جو سال کے کسی بھی وقت کے لیے بہترین ہے۔ پرانے طرز کے اوٹس، سیب اور کیلیفورنیا کھجور کی قدرتی مٹھاس سے بنا یہ بیک ایک غذائیت سے بھرپور ڈش ہے جس میں کوئی اضافی چینی نہیں ہے۔ یہ ناشتہ، سائیڈ ڈش، اسنیک یا میٹھا بن سکتا ہے۔ مزید یہ کہ یہ اوٹ بیک فائبر سے بھرپور ہے جو آپ کو پیٹ بھرا اور توانا رکھتا ہے۔","8","1 چوکور ٹکڑا",
["1 کپ پرانے طرز کے رولڈ اوٹس","1 کپ سکم دودھ","1 1/2 بڑا سیب (گٹھلی نکلا ہوا اور کٹا ہوا)","1/2 کپ منجمد کرین بیریاں","6 درمیانی کیلیفورنیا کھجوریں (گٹھلی نکلی ہوئی اور کٹی ہوئی)","1/4 کپ پیکان","1 کھانے کا چمچ میدہ","2 بڑے انڈے","1 چائے کا چمچ پسی ہوئی دار چینی","1/2 چائے کا چمچ پسا ہوا جائفل","1 چائے کا چمچ ونیلا ایسنس","1 چائے کا چمچ بیکنگ پاؤڈر","1/4 چائے کا چمچ نمک"],
["اوون کو 350°F پر پہلے سے گرم کریں اور 8x8 کی بیکنگ ڈش پر ہلکا سا چکنائی لگا دیں۔","ایک بڑے پیالے میں اوٹس، کیلیفورنیا کھجوریں، کٹے ہوئے سیب، کرین بیریاں، پیکان، دار چینی، جائفل، بیکنگ پاؤڈر، میدہ اور نمک اچھی طرح مل جانے تک ملائیں۔","انڈے، دودھ اور ونیلا ایسنس پھینٹ کر ملا دیں۔","آمیزہ تیار کی ہوئی بیکنگ ڈش میں ڈالیں اور یکساں پھیلا دیں۔","35–40 منٹ بیک کریں، یا جب تک دلیہ جم نہ جائے اور اوپر سے سنہری بھورا نہ ہو جائے۔","پیش کرنے سے پہلے چند منٹ ٹھنڈا ہونے دیں۔ 8 برابر چوکور ٹکڑوں میں کاٹ لیں۔","پہلے سے کھانا تیار رکھنے (میل پریپ) کے لیے ریفریجریٹر میں پانچ دن تک رکھیں۔"]),
R(6388872,"کالی پھلیوں اور آڑو کا سالسا","شیف کا راز: اگر آپ چاہیں تو آڑو کی جگہ آم استعمال کیا جا سکتا ہے۔","24","2 کھانے کے چمچ",
["1/4 چائے کا چمچ کالی مرچ","1/8 چائے کا چمچ نمک","2 کھانے کا چمچ لال پیاز (باریک کٹا ہوا)","4 کھانے کا چمچ لیموں کا رس (2 لیموں سے)","1/2 کپ تازہ بقدونس (کٹا ہوا)","1 کھانے کا چمچ زیتون کا تیل","1/2 چائے کا چمچ پسا ہوا زیرہ","2 درمیانے آڑو (چوکور کٹے ہوئے)","1 (15 اونس) ڈبہ کالی پھلیاں (چھان کر دھوئی ہوئی)"],
["تمام اجزاء کو یکساں طور پر مل جانے تک ملا لیں۔ پیش کرنے تک ریفریجریٹر میں رکھیں۔"]),
R(6389870,"کم خرچ ڈیلکس چکن ناچوز","آپ ان ناچوز کو اپنی پسند کے مطابق جتنا چاہیں تیز مسالے والا بنا سکتے ہیں، اپنی پسندیدہ تیزی کے درجے کا سالسا خرید کر۔ اگر آپ اور بھی تیز پسند کرتے ہیں تو دہی کے اوپر ہاٹ ساس کے چند قطرے ڈالیں۔","8","ترکیب کا 1/8",
["1 اسپرے، 0.25 گرام نان اسٹک کوکنگ اسپرے","8 چھوٹے مکئی کے ٹورٹیلاز (ہر ایک 6 ٹکڑوں میں کٹا ہوا)","1/2 چائے کا چمچ نمک (اختیاری)","15 اونس، 1 ڈبہ ری فرائیڈ بینز (بغیر چکنائی کے)","1/4 کپ کم سوڈیم چکن شوربہ (کم سوڈیم)","1 پاؤنڈ چکن بریسٹ (بغیر ہڈی اور بغیر کھال کے، پکے ہوئے اور ریزہ کیے ہوئے)","1/2 کپ میکسیکن طرز کا پنیر (کم چکنائی والا، کدوکش کیا ہوا)","2 درمیانے ٹماٹر (بیج نکالے ہوئے اور چوکور کٹے ہوئے)","1/2 کپ سالسا","1 درمیانہ ایووکاڈو (گٹھلی نکلا ہوا اور چوکور کٹا ہوا)","2 کپ لیٹش (باریک کٹی ہوئی)","1/2 کپ سادہ بغیر چکنائی کا یونانی دہی (بغیر چکنائی کا)"],
["اوون کو 350 ڈگری فارن ہائیٹ پر پہلے سے گرم کریں۔ ایک بڑی یا دو چھوٹی بیکنگ شیٹس پر کوکنگ اسپرے لگائیں۔","کٹے ہوئے مکئی کے ٹورٹیلاز کو بیکنگ شیٹ(س) پر ایک تہہ میں بچھائیں۔ اوپر کوکنگ اسپرے کریں۔ ہلکا سا نمک چھڑکیں (اختیاری)۔","20 منٹ بیک کریں، ہر 5 منٹ بعد ہلاتے رہیں یا جب تک چپس ہلکے سنہری بھورے اور کرارے نہ ہو جائیں۔ اوون سے نکالیں اور کوکنگ اسپرے لگی بیکنگ ڈش میں ڈال دیں۔ ایک طرف رکھ دیں۔","بغیر چکنائی والی ری فرائیڈ بینز کو چکن شوربے کے ساتھ ملائیں اور بیک کیے ہوئے ٹورٹیلا چپس پر ڈال دیں۔","پھلیوں کے اوپر ریزہ کیا ہوا چکن اور پھر کم چکنائی والا پنیر ڈالیں۔","اوون کے اوپری ریک پر رکھیں اور 10-15 منٹ بیک کریں یا جب تک پنیر پگھل کر سنہری ہونا شروع نہ ہو جائے۔","اوون سے نکالیں اور ناچوز کو آٹھ پلیٹوں میں تقسیم کریں۔ ہر پلیٹ پر چوکور کٹے ٹماٹر، سالسا، 1/4 ایووکاڈو، لیٹش اور دہی ڈالیں۔"]),
